cypress_script:
describe('Sortable Data Tables', () => {
  it('should display sortable tables with correct headers', () => {
    cy.visit('https://the-internet.herokuapp.com/tables');
    cy.get('table#table1').should('be.visible');
    cy.get('table#table2').should('be.visible');
    cy.get('table#table1').contains('Last Name');
    cy.get('table#table1').contains('First Name');
    cy.get('table#table1').contains('Email');
    cy.get('table#table1').contains('Due');
    cy.get('table#table1').contains('Web Site');
    cy.get('table#table1').contains('Action');
  });

  it('should not change URL when sorting', () => {
    cy.visit('https://the-internet.herokuapp.com/tables');
    cy.url().should('eq', 'https://the-internet.herokuapp.com/tables');
    // Assuming the table can be sorted by clicking the headers
    cy.get('table#table1 th').first().click();
    cy.url().should('eq', 'https://the-internet.herokuapp.com/tables');
  });
});

playwright_script:
import { test, expect } from '@playwright/test';

test.describe('Sortable Data Tables', () => {
  test('should display sortable tables with correct headers', async ({ page }) => {
    await page.goto('https://the-internet.herokuapp.com/tables');
    await expect(page.locator('table#table1')).toBeVisible();
    await expect(page.locator('table#table2')).toBeVisible();
    await expect(page.locator('table#table1')).toContainText('Last Name');
    await expect(page.locator('table#table1')).toContainText('First Name');
    await expect(page.locator('table#table1')).toContainText('Email');
    await expect(page.locator('table#table1')).toContainText('Due');
    await expect(page.locator('table#table1')).toContainText('Web Site');
    await expect(page.locator('table#table1')).toContainText('Action');
  });

  test('should not change URL when sorting', async ({ page }) => {
    await page.goto('https://the-internet.herokuapp.com/tables');
    const initialUrl = page.url();
    await page.locator('table#table1 th').first().click();
    expect(page.url()).toBe(initialUrl);
  });
});
